package com.tripmateai.service.impl; import com.tripmateai.dto.request.favorite.*; import com.tripmateai.dto.response.favorite.*; import com.tripmateai.entity.*; import com.tripmateai.enums.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.FavoriteMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.FavoriteService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class FavoriteServiceImpl implements FavoriteService {private final FavoriteRepository favorites;private final DestinationRepository destinations;private final HotelRepository hotels;private final RestaurantRepository restaurants;private final AttractionRepository attractions;private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal u))throw new UnauthorizedException("Authentication required");return u.user();} public FavoriteResponse add(CreateFavoriteRequest r){var u=user();var f=new Favorite();f.setUser(u);switch(r.targetType()){case DESTINATION->{var x=destinations.findById(r.targetId()).orElseThrow(()->new ResourceNotFoundException("Destination not found"));if(favorites.existsByUserAndDestination(u,x))throw new BadRequestException("Target is already favorited");f.setDestination(x);}case HOTEL->{var x=hotels.findById(r.targetId()).orElseThrow(()->new ResourceNotFoundException("Hotel not found"));if(favorites.existsByUserAndHotel(u,x))throw new BadRequestException("Target is already favorited");f.setHotel(x);}case RESTAURANT->{var x=restaurants.findById(r.targetId()).orElseThrow(()->new ResourceNotFoundException("Restaurant not found"));if(favorites.existsByUserAndRestaurant(u,x))throw new BadRequestException("Target is already favorited");f.setRestaurant(x);}case ATTRACTION->{var x=attractions.findById(r.targetId()).orElseThrow(()->new ResourceNotFoundException("Attraction not found"));if(favorites.existsByUserAndAttraction(u,x))throw new BadRequestException("Target is already favorited");f.setAttraction(x);}}return FavoriteMapper.toResponse(favorites.save(f));} @Transactional(readOnly=true) public List<FavoriteResponse> list(FavoriteTargetType type){return favorites.findByUser(user()).stream().filter(f->type==null||FavoriteMapper.toResponse(f).targetType()==type).map(FavoriteMapper::toResponse).toList();} @Transactional(readOnly=true) public boolean check(FavoriteTargetType type,Long id){return favorites.findByUser(user()).stream().map(FavoriteMapper::toResponse).anyMatch(f->f.targetType()==type&&f.targetId().equals(id));} public void delete(Long id){favorites.delete(favorites.findByIdAndUser(id,user()).orElseThrow(()->new ResourceNotFoundException("Favorite not found")));}}
